# region: sift
def sift(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: render
def render(xs, limit=12):
    return [v if v <= limit else limit for v in xs]

# region: shape
def shape(xs, floor_=3):
    return [v for v in xs if v >= floor_]

# region: digest
def digest(xs, offset=4):
    return [v + offset for v in xs]

# region: gather
def gather(xs, cut=3):
    lo = [v for v in xs if v < cut]
    hi = [v for v in xs if v >= cut]
    return {'n': len(xs), 'lo': len(lo), 'hi': len(hi)}

# region: intake
def intake(summary, bar=3):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) > bar else 'low'
    return out

# region: run
def run(raw):
    return intake(gather(digest(shape(render(sift(raw))))))

